+  const used = consume(store, 2, 3, { at, ref: "recipe:2" });
+  assert.deepEqual(used, [
+    { batchId: 4, qty: 2 },
+    { batchId: 3, qty: 1 },
+  ]);
+});
+
+test("FEFO: no expiry goes last; same expiry goes received first, then lower id", () => {
+  const store = fresh();
+  store.data.batches.push(
+    { id: 100, itemId: 2, lot: "X-NOEXP", qty: 1, receivedOn: "2026-10-01", expires: null, location: "fridge" },
